use jsonwebtoken::{decode, encode, Algorithm, DecodingKey, EncodingKey, Header, Validation};
use std::sync::{Arc, Mutex};
use std::collections::HashMap;

// Connection pool for image processing workers
pub struct ConnectionPool {
    connections: Vec<WorkerConnection>,
    max_size: usize,
}

pub struct WorkerConnection {
    id: u32,
    active: bool,
}

#[derive(Debug, serde::Serialize, serde::Deserialize, Clone)]
pub struct Claims {
    pub sub: String,
    pub role: String,
    pub pipeline_access: Vec<String>,
    pub exp: usize,
}

pub struct AuthConfig {
    pub rsa_public_key: Vec<u8>,
    pub hmac_secret: Vec<u8>,
    // Supported algorithms registry
    pub algorithm_registry: HashMap<String, AlgorithmEntry>,
}

#[derive(Clone)]
pub struct AlgorithmEntry {
    pub algorithm: Algorithm,
    pub key_source: KeySource,
}

#[derive(Clone)]
pub enum KeySource {
    RsaPublic,
    HmacShared,
}

impl AuthConfig {
    pub fn new(rsa_pub_pem: &[u8], hmac_secret: &[u8]) -> Self {
        let mut registry = HashMap::new();
        registry.insert("RS256".to_string(), AlgorithmEntry {
            algorithm: Algorithm::RS256,
            key_source: KeySource::RsaPublic,
        });
        registry.insert("HS256".to_string(), AlgorithmEntry {
            algorithm: Algorithm::HS256,
            key_source: KeySource::HmacShared,
        });
        AuthConfig {
            rsa_public_key: rsa_pub_pem.to_vec(),
            hmac_secret: hmac_secret.to_vec(),
            algorithm_registry: registry,
        }
    }
}

pub struct ImagePipeline {
    pool: Arc<Mutex<ConnectionPool>>,
    auth_config: Arc<AuthConfig>,
}

impl ImagePipeline {
    pub fn new(pool_size: usize, auth_config: AuthConfig) -> Self {
        let connections = (0..pool_size)
            .map(|i| WorkerConnection { id: i as u32, active: false })
            .collect();
        ImagePipeline {
            pool: Arc::new(Mutex::new(ConnectionPool {
                connections,
                max_size: pool_size,
            })),
            auth_config: Arc::new(auth_config),
        }
    }

    /// Validates the JWT and returns claims if the token is authorized
    /// for the requested pipeline operation.
    pub fn validate_token(&self, token: &str) -> Result<Claims, String> {
        // Extract header to determine algorithm
        let header = jsonwebtoken::decode_header(token)
            .map_err(|e| format!("Header decode error: {}", e))?;

        let alg_name = format!("{:?}", header.alg);

        // Look up algorithm in registry to get the appropriate key source
        let entry = self.auth_config.algorithm_registry.get(&alg_name)
            .ok_or_else(|| format!("Unsupported algorithm: {}", alg_name))?;

        // Resolve the decoding key based on the key source indicated by the registry
        let decoding_key = self.resolve_decoding_key(&entry.key_source)?;

        // Build validation with the algorithm from the REGISTRY, not the header
        let mut validation = Validation::new(entry.algorithm);
        validation.validate_exp = true;

        let token_data = decode::<Claims>(token, &decoding_key, &validation)
            .map_err(|e| format!("Token validation failed: {}", e))?;

        Ok(token_data.claims)
    }

    fn resolve_decoding_key(&self, source: &KeySource) -> Result<DecodingKey, String> {
        match source {
            KeySource::RsaPublic => {
                DecodingKey::from_rsa_pem(&self.auth_config.rsa_public_key)
                    .map_err(|e| format!("RSA key error: {}", e))
            }
            KeySource::HmacShared => {
                Ok(DecodingKey::from_secret(&self.auth_config.hmac_secret))
            }
        }
    }

    pub fn process_image(&self, token: &str, image_data: &[u8], operation: &str) -> Result<Vec<u8>, String> {
        let claims = self.validate_token(token)?;

        if !claims.pipeline_access.contains(&operation.to_string()) {
            return Err("Insufficient pipeline access".to_string());
        }

        // Acquire connection from pool
        let mut pool = self.pool.lock().map_err(|_| "Pool lock poisoned".to_string())?;
        let conn = pool.connections.iter_mut()
            .find(|c| !c.active)
            .ok_or("No available connections")?;
        conn.active = true;
        let conn_id = conn.id;
        drop(pool);

        // Simulate image processing
        let result = self.execute_pipeline(conn_id, image_data, operation)?;

        // Release connection
        let mut pool = self.pool.lock().map_err(|_| "Pool lock poisoned".to_string())?;
        if let Some(conn) = pool.connections.iter_mut().find(|c| c.id == conn_id) {
            conn.active = false;
        }

        Ok(result)
    }

    fn execute_pipeline(&self, _conn_id: u32, image_data: &[u8], operation: &str) -> Result<Vec<u8>, String> {
        match operation {
            "resize" => Ok(image_data.to_vec()),
            "compress" => Ok(image_data.to_vec()),
            "watermark" => Ok(image_data.to_vec()),
            _ => Err(format!("Unknown operation: {}", operation)),
        }
    }
}

